items.outputText:
{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회 쿼리의 분석 결과를 개선 방법 선택으로 연결할 수 있는지 검증한다. 실행 계획에서 확인한 내용이 인덱스 추가 결정의 근거가 된 연결에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회가 느려 쿼리 개선이 필요했던 상황이다.",
          "task": "실행 계획에서 드러난 병목을 바탕으로 인덱스 추가가 적절한 개선 방법인지 판단해야 했다.",
          "action": "실행 계획에서 확인한 테이블 접근 방식이나 조회 범위를 실제 조회 조건과 대조해 인덱스 추가의 근거로 삼은 내용을 설명한다.",
          "result": "선택한 인덱스가 확인된 병목을 어떤 원리로 줄일 수 있었는지 드러난다. 별도의 개선 전후 측정 설명은 필수로 요구하지 않는다."
        },
        "expectedEvidence": [
          "인덱스 추가 결정의 근거로 삼은 실행 계획의 구체적인 내용",
          "해당 실행 계획 내용이 신고 목록 조회의 병목을 나타낸다고 판단한 이유",
          "확인한 병목과 추가한 인덱스의 역할 사이의 연결"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회를 3.2초에서 0.4초로 줄이셨던데요, 그때 인덱스 추가를 결정하는 데 근거가 된 실행 계획의 내용은 무엇이었어요?",
      "answerTip": "기억나는 장면을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제로 확인한 실행 계획 내용을 구체적으로 제시하고, 그것이 병목을 나타내는 이유를 타당하게 설명한다.",
            "조회 조건에 비추어 해당 분석 결과가 인덱스 추가 결정으로 이어진 연결과 기대 효과를 명확히 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "실행 계획에서 확인한 병목과 인덱스 추가의 관련성은 설명하지만, 확인한 내용이나 판단 이유가 일부 모호하다.",
            "인덱스로 조회 부담을 줄이려 했다는 설명은 있으나 실제 조회 조건과 연결한 설명이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "실행 계획에서 어떤 내용을 확인했는지 밝히지 못하고 인덱스를 추가했다는 사실이나 성능 수치만 제시한다.",
            "제시한 분석 내용과 인덱스 추가 결정 사이의 연결이 없거나 기술적으로 타당하지 않다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "운영 오류의 원인에 맞는 복구 조치를 실제로 적용할 수 있는지 검증한다. 두 서버의 스케줄러 중복 실행을 막기 위해 잠금 키를 적용한 행동에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 후 알림이 중복 발송됐고, 로그를 통해 두 서버에서 스케줄러가 동시에 실행되는 상황을 확인했다.",
          "task": "여러 서버에서 같은 알림 작업을 중복 실행하지 않도록 복구 조치를 적용해야 했다.",
          "action": "잠금 키를 어느 실행 지점에 적용했으며, 잠금 여부에 따라 스케줄러 실행을 어떻게 제어했는지 실제 구현한 범위에서 설명한다.",
          "result": "잠금 적용으로 두 서버의 중복 실행을 차단하는 방식이 드러난다. 별도의 재발 방지 절차나 장기 운영 성과는 필수로 요구하지 않는다."
        },
        "expectedEvidence": [
          "스케줄러 중복 실행을 막기 위해 잠금 키를 실제로 적용한 방식",
          "서로 다른 서버의 실행을 같은 잠금으로 제어할 수 있었던 구조",
          "잠금 여부에 따라 중복 작업의 실행을 차단한 동작"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림 중복 발송을 잠금 키로 고치셨다고 하셨는데요, 그때 여러 서버의 동시 실행을 막는 잠금은 어떻게 적용하셨어요?",
      "answerTip": "직접 했던 일을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "잠금을 적용한 실행 지점과 잠금 여부에 따른 작업 실행 제어를 실제 행동으로 구체적으로 설명한다.",
            "서로 다른 서버에서도 같은 작업의 중복 실행을 막을 수 있는 구조를 타당하게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "잠금을 통해 한 서버만 작업을 실행하도록 했다는 핵심 조치는 설명한다.",
            "잠금을 적용한 지점이나 서버 간 실행 제어 방식에 대한 설명은 일부 부족하지만, 중복 실행을 막는 기본 동작은 확인된다."
          ]
        },
        "poor": {
          "criteria": [
            "잠금 키를 사용했다는 말만 있고 실제 적용 방식이나 실행 제어 동작을 설명하지 못한다.",
            "설명한 잠금 방식으로는 서로 다른 서버의 중복 실행을 막을 수 없거나, 복구 조치 대신 장애 경위만 설명한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "현업 요청의 목적을 기능 범위 결정으로 연결할 수 있는지 검증한다. 세탁소 인터뷰 내용 중 어떤 요청을 근거로 기능 하나의 포함 여부를 결정했는지에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "세탁소 인터뷰에서 예약 서비스에 대한 요청을 수집하고 개발 담당 팀원과 구현 범위를 조정한 상황이다.",
          "task": "요청의 목적과 서비스 범위를 바탕으로 특정 기능의 포함 여부를 정해야 했다.",
          "action": "인터뷰에서 확인한 구체적인 요청이나 불편을 해석하고, 해당 내용이 기능 포함 여부를 결정하는 근거가 된 이유를 설명한다.",
          "result": "제시한 인터뷰 내용에 따라 해당 기능을 포함하거나 제외한 결정이 드러난다. 실제 개발 완료나 성과 수치는 요구하지 않는다."
        },
        "expectedEvidence": [
          "기능 하나의 포함 여부를 결정하는 근거로 사용한 구체적인 세탁소 인터뷰 내용",
          "해당 요청에서 파악한 목적이나 해결할 문제",
          "요청의 목적과 기능 포함 여부 사이의 타당한 연결"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 개발 담당 팀원과 범위를 조정하셨던데요, 그때 기능 하나의 포함 여부를 결정한 근거가 된 세탁소 인터뷰 내용은 무엇이었어요?",
      "answerTip": "기억나는 사례 하나를 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "기능 포함 여부의 근거로 사용한 실제 인터뷰 내용을 구체적으로 제시한다.",
            "인터뷰 내용에서 파악한 요청의 목적과 기능 포함 또는 제외 결정이 타당하게 연결된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "인터뷰 요청과 기능 포함 여부를 제시하지만 요청 내용이나 목적에 대한 설명이 포괄적이다.",
            "요청과 범위 결정의 관련성은 확인되지만 해당 요청이 결정 근거가 된 이유는 충분히 드러나지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "인터뷰를 진행했다는 사실만 말하고 범위 결정의 근거로 사용한 내용을 제시하지 못한다.",
            "기능 포함 여부를 설명하더라도 인터뷰에서 확인한 요청의 목적과 연결되지 않는다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황을 실제로 구현 가능한 화면 동작으로 구체화할 수 있는지 검증한다. 화면설계서에 담은 예외 상황 하나에서 사용자가 보게 되는 화면 동작에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "예약 서비스의 화면설계서를 작성하며 정상 흐름에서 벗어나는 예외 상황을 다룬 장면이다.",
          "task": "해당 예외 상황에서 화면이 어떤 상태로 바뀌고 사용자에게 어떤 동작을 제공할지 정해야 했다.",
          "action": "예외 발생 조건에 대응하는 화면 동작을 구체적으로 설명한다. 안내 문구나 버튼 반응은 해당 동작을 이해하는 데 필요한 범위에서 제시한다.",
          "result": "예외 발생 후 사용자가 보게 될 화면의 반응과 다음에 가능한 행동이 명확해진다. 실제 구현이나 사용자 검증 결과는 요구하지 않는다."
        },
        "expectedEvidence": [
          "예외 상황 하나에 대해 설계한 구체적인 화면 동작",
          "해당 화면 동작이 발생하는 예외 조건",
          "화면 동작을 통해 사용자가 현재 상태와 다음에 가능한 행동을 알 수 있는지 확인할 수 있는 설명"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 화면설계서 28장을 작성하셨던데요, 그중 예외 상황 하나에서 사용자에게 보일 화면 동작을 어떻게 설계하셨어요?",
      "answerTip": "한 장면을 떠올리며 차근차근 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "예외 발생 조건과 그에 따른 화면 동작을 구현 시 해석이 엇갈리지 않을 정도로 구체적으로 설명한다.",
            "설계한 화면 반응을 통해 사용자가 현재 상태와 다음에 가능한 행동을 파악할 수 있다."
          ]
        },
        "acceptable": {
          "criteria": [
            "특정 예외 상황에 대한 화면 동작은 제시하지만 발생 조건이나 화면 반응의 설명이 일부 모호하다.",
            "사용자에게 상태를 알려 주는 방식은 드러나지만 이후 가능한 행동은 명확하지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "예외 상황을 고려했다는 설명에 그치고 실제로 설계한 화면 동작을 제시하지 못한다.",
            "화면 동작이 예외 발생 조건과 맞지 않거나 사용자가 어떤 상태를 보게 되는지 알 수 없다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "의심스러운 처방을 확인 없이 수행하지 않는지 검증한다. 진통제 처방의 이상을 감지하고 투약을 보류한 판단 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 입력된 상황이다.",
          "task": "처방된 용량을 그대로 투여해도 되는지 확인하기 전 투약 진행 여부를 판단해야 했다.",
          "action": "처방 용량에서 발견한 차이를 구체적으로 짚고, 확인이 필요한 이상으로 판단해 투약을 보류한 이유를 설명한다.",
          "result": "처방의 적절성이 확인되지 않은 상태에서 투약이 진행되는 것을 막았다는 판단의 직접적인 의미가 드러난다."
        },
        "expectedEvidence": [
          "진통제 투약을 보류하기로 판단한 구체적인 근거",
          "처방 용량의 이상을 알아차리는 데 비교 대상으로 삼은 정보",
          "발견한 차이를 확인 없이 투약해서는 안 되는 문제로 본 이유"
        ]
      },
      "question": "푸른결종합병원에서 수술 후 환자의 진통제 처방 용량이 평소의 두 배여서 투약을 멈추셨다고 하셨는데요, 그때 투약을 보류한 판단 근거는 무엇이었어요?",
      "answerTip": "당시 장면을 떠올리며 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "처방 용량을 어떤 정보와 비교해 이상하다고 판단했는지 구체적으로 설명한다.",
            "평소와 다르다는 사실만으로 오류를 단정하지 않고, 적절성이 확인되기 전에는 투약을 보류해야 한다는 판단을 명확히 설명한다.",
            "제시한 근거와 투약 보류 결정이 일관되게 연결된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "평소보다 많은 처방 용량을 보고 확인이 필요해 투약을 보류했다고 설명한다.",
            "다만 비교한 정보나 해당 차이를 위험 신호로 판단한 이유가 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 보류한 근거를 제시하지 못하고 평소에도 조심한다는 일반적인 설명에 그친다.",
            "이상 여부가 확인되지 않았더라도 처방대로 투약하면 된다는 판단을 제시하거나, 질문과 무관한 투약 경험만 설명한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "관찰해 기록한 환자 상태 변화를 다음 근무자의 간호에 필요한 정보로 전달할 수 있는지 검증한다. 실제 인수인계에서 전달한 상태 변화의 내용에 초점을 둔다.",
